/**
 * The delivery side category list view class. Makes a call to the service to get page list entries
 * and renders them in the list.
 * On document ready loops through all perc-category-list elements on the page and finds the query from the data attribute
 * on them. Passes the query and gets the entries from the service. If service returns an error, logs the error and
 * does nothing.
 */
var strJSON;
var pageResult;
var baseURL;
var isEditMode;
var isPreviewMode;
(function ($) {
  $(document).ready(function () {
    $.PercCategoryListView.updateCategoryList();
  });
  $.PercCategoryListView = {
    updateCategoryList: updateCategoryList,
  };
  var pageResult;
  var baseURL;
  var strJSON;
  var nRow;
  function updateCategoryList() {
    $(".perc-category-list").each(function () {
      updateOneCategoryList($(this));
    });
  }

  // Parse the data-query attribute of one category list element. Returns null
  // when the element carries no query and must be skipped; otherwise returns
  // the parsed query plus the extracted render options. Stashes the shared
  // render state (pageResult, edit/preview mode) in the module globals that
  // parseNode() reads, exactly as the inline code did before extraction.
  function readListQuery(currentCategoryList) {
    if ("" === currentCategoryList.attr("data-query")) {
      return null;
    }
    var queryString = JSON.parse(currentCategoryList.attr("data-query"));
    //Get the result page to display the pages for each category
    var pageResultOption = queryString.category_page_result;
    delete queryString.category_page_result;
    //Get the display option (Expanded hierarchy = "expanded", Collapsible = "collapsible")
    var display = queryString.display_option;
    delete queryString.display_option;
    //Get the max categories option
    //set the tree pre-expanded level for Collapsible option or the row number to show for the Expanded hierarchy
    var maxCat = queryString.max_categories;
    delete queryString.max_categories;
    isEditMode = queryString.isEditMode;
    isPreviewMode = queryString.isPreviewMode;
    pageResult = pageResultOption;
    return { queryString: queryString, display: display, maxCat: maxCat };
  }

  //Set the base URL to create the href for each item
  function resolveBaseURL() {
    if (isEditMode === "true" || isPreviewMode == "true") {
      var paths = window.location.pathname.split("/");
      // mkd-code-review[paths.hardcoded_sep]: adjudicated intentional (issue #6195,
      // same as #5897/#5898/#5910/#5927) — slashes join browser URL pathname
      // segments (URLs always use "/"), not an OS filesystem path.
      return "/" + paths[1] + "/" + paths[2];
    }
    return window.location.protocol + "//" + window.location.host;
  }

  function updateOneCategoryList(currentCategoryList) {
    var parsed = readListQuery(currentCategoryList);
    if (null === parsed) {
      return;
    }
    baseURL = resolveBaseURL();
    strJSON = JSON.stringify(parsed.queryString);
    nRow = 0;

    $.PercCategoryListService.getCategories(
      parsed.queryString,
      function (status, categoryEntries) {
        handleCategoryResponse(
          currentCategoryList,
          parsed,
          status,
          categoryEntries,
        );
      },
    );
  }

  function handleCategoryResponse(
    currentCategoryList,
    parsed,
    status,
    categoryEntries,
  ) {
    categoryEntries = $.PercServiceUtils.toJSON(categoryEntries);

    if (!status) {
      //Log the error and leave the original list entries as is
      console.error(status);
      return;
    }
    if (0 === categoryEntries.length) {
      return;
    }
    renderCategoryEntries(currentCategoryList, categoryEntries, parsed);
  }

  function renderCategoryEntries(currentCategoryList, categoryEntries, parsed) {
    //Clean the HTML generated by CMS
    currentCategoryList
      .find(".perc-category-list-expanded,.perc-category-list-collapsible")
      .empty();
    //Destroy previous element of FancyTree.
    currentCategoryList.find(".perc-category-list-collapsible").fancytree("destroy");

    if ("collapsible" === parsed.display) {
      renderCollapsibleTree(currentCategoryList, categoryEntries, parsed.maxCat);
    } else {
      //Full expanded Tree
      renderExpandedTree(currentCategoryList, categoryEntries, parsed.maxCat);
    }

    //currentCategoryList.find(".perc-category-list-expanded,.perc-category-list-collapsible").show();
  }

  function renderCollapsibleTree(currentCategoryList, categoryEntries, maxCat) {
    //Collapsible Tree
    var ul = createNestedUlLiTreeCollapsible(categoryEntries, "", maxCat, 0);
    currentCategoryList.find(".perc-category-list-collapsible").html(ul);
    currentCategoryList.find(".perc-category-list-collapsible").fancytree({
      minExpandLevel: 2,
      onActivate: onCollapsibleNodeActivate,
    });
  }

  function onCollapsibleNodeActivate(node) {
    var href = $(node.data.title).attr("href");
    var count = $(node.data.title).attr("data-count");
    if (0 < count && isEditMode !== "true") {
      window.location.href = href;
    }
  }

  function renderExpandedTree(currentCategoryList, categoryEntries, maxCat) {
    var ul = createNestedUlLiTreeExpanded(categoryEntries, "", maxCat, 0);
    currentCategoryList.find(".perc-category-list-expanded").html(ul);
  }

  //Generate the structure for the Full expanded tree using UL and LI
  function createNestedUlLiTreeExpanded(treeNodes, parentPath, maxRow, nLevel) {
    var ul = "";
    if (maxRow > nRow || 0 == maxRow) {
      ul = $("<ul>")
        .addClass("perc-category-elements")
        .addClass("perc-category-level" + nLevel);
      for (var n = 0; n < treeNodes.length; n++) {
        if (maxRow > nRow || 0 == maxRow) {
          var node = treeNodes[n];
          // mkd-code-review[paths.hardcoded_sep]: adjudicated intentional (issue #6195,
          // same as #5897/#5898/#5910/#5927) — slash joins CMS logical category
          // path segments used in perc:category queries, not an OS path.
          node.path = parentPath + "/" + node.category;
          var li = parseNode(node, nLevel);
          ul.append(li);
          nRow++;
          if (node.children && 0 < node.children.length) {
            li.append(
              createNestedUlLiTreeExpanded(
                node.children,
                node.path,
                maxRow,
                nLevel + 1,
              ),
            );
          }
        }
      }
    }
    return ul;
  }

  //Generate the structure for the Collapsible Tree using FancyTree plugin
  function createNestedUlLiTreeCollapsible(
    treeNodes,
    parentPath,
    maxRow,
    nLevel,
  ) {
    var ul;
    ul = $("<ul>")
      .addClass("perc-category-elements")
      .addClass("perc-category-level" + nLevel);

    for (var n = 0; n < treeNodes.length; n++) {
      if (1 !== nLevel || n < maxRow || 0 == maxRow) {
        var node = treeNodes[n];
        // mkd-code-review[paths.hardcoded_sep]: adjudicated intentional (issue #6195,
        // same as #5897/#5898/#5910/#5927) — slash joins CMS logical category
        // path segments used in perc:category queries, not an OS path.
        node.path = parentPath + "/" + node.category;
        var li = parseNode(node);
        ul.append(li);
        if (node.children && 0 < node.children.length) {
          li.append(
            createNestedUlLiTreeCollapsible(
              node.children,
              node.path,
              maxRow,
              nLevel + 1,
            ),
          );
        }
      }
    }
    return ul;
  }

  //Create the LI node from a Category.
  function parseNode(node) {
    var countTotal = node.count.first;
    var nodeStr = node.category;
    if (countTotal > 0) nodeStr = node.category + " (" + countTotal + ")";
    var query = JSON.parse(strJSON);
    query.criteria.push("perc:category LIKE '" + node.path + "%'");
    var encodedQuery = "&query=" + encodeURIComponent(JSON.stringify(query));

    var href = "#";
    if (
      isEditMode === "true" ||
      "undefined" === typeof pageResult ||
      "" === pageResult
    ) {
      href = "#";
    } else {
      href = baseURL + pageResult + "?filter=" + node.category + encodedQuery;
    }

    var a = $("<a>")
      // CodeQL js/xss-through-dom (alert #985): href is built from
      // node.category (server-supplied data, treated as user-controllable for
      // defense in depth); sanitize before assignment.
      .attr("href", $.PercServiceUtils.sanitizeUrlForHref(href))
      .attr("data-count", countTotal)
      .attr("title", nodeStr)
      .addClass("perc-node")
      .append(nodeStr);

    return $("<li>").addClass("perc-category-element").append(a);
  }
})(jQuery);
